Class MoneyBox
  Define gathered As Integer;

  Method Constructor()
    This.gathered <- 0;
  EndMethod

  Method Deposit(coins As Integer)
    This.gathered <- This.gathered + coins;
  EndMethod

  Method Total() As Integer
    Return This.gathered;
  EndMethod
EndClass

Algorithm Savings
  Define moneyBox As MoneyBox <- New MoneyBox();
  Define coins As Integer;
  Read coins;
  While coins <> 0 Do
    moneyBox.Deposit(coins);
    Read coins;
  EndWhile
  Write moneyBox.Total();
EndAlgorithm
